# Ten + mo ta hien tren kho: noi script LAM DUOC GI cho nguoi dung (khong ghi chu thu nghiem/log)
M = {
"01-go-onedrive": ("Gỡ OneDrive", "[Dọn sẵn] Gỡ OneDrive khỏi máy và không cho nó tự cài lại cho tài khoản tạo sau. Máy hết biểu tượng và lời nhắc đăng nhập OneDrive."),
"02-tat-hibernate": ("Tắt Hibernate", "[Dọn sẵn] Tắt chế độ ngủ đông và xoá file hiberfil.sys, lấy lại vài GB ổ C (bằng khoảng 40% RAM). Tắt luôn Fast Startup."),
"03-tat-reserved-storage": ("Tắt Reserved Storage", "[Dọn sẵn] Giải phóng khoảng 7 GB ổ C mà Windows giữ sẵn cho cập nhật. Nên chạy trước khi Windows Update chạy lần đầu; dung lượng được trả lại sau khi khởi động lại."),
"04-bat-storage-sense": ("Bật Storage Sense", "[Dọn sẵn] Bật tính năng tự dọn của Windows: tự xoá file tạm và dọn thùng rác sau 30 ngày, ổ đĩa không bị đầy dần theo thời gian."),
"05-tat-phim-dinh": ("Tắt phím dính", "[Giao diện] Bấm Shift 5 lần không còn hiện hộp thoại Sticky Keys/Filter Keys gây khó chịu, kể cả ở màn hình đăng nhập."),
"06-dong-ho-24h": ("Đồng hồ 24 giờ, tuần bắt đầu thứ Hai", "[Giao diện] Đồng hồ hiện giờ 24 (14:30:00) và lịch bắt đầu tuần từ thứ Hai, đúng thói quen người Việt."),
"07-dinh-dang-viet-nam": ("Định dạng Việt Nam", "[Giao diện] Đặt vùng Việt Nam: ngày hiện dd/MM/yyyy, giờ 24h, số và tiền tệ theo kiểu Việt Nam. Không đổi ngôn ngữ giao diện Windows."),
"08-bat-clipboard-history": ("Bật lịch sử Clipboard", "[Giao diện] Bật lịch sử clipboard: bấm Windows + V để dán lại các thứ đã chép trước đó."),
"09-tat-spotlight-khoa": ("Tắt Spotlight màn hình khoá", "[Giao diện] Màn hình khoá không đổi ảnh và không hiện quảng cáo, gợi ý của Windows Spotlight."),
"10-tat-game-mode-dvr": ("Tắt Game Mode và Game DVR", "[Giao diện] Tắt Game Bar, quay màn hình nền và Game Mode tự bật - bớt chiếm tài nguyên và hết hiện cửa sổ game khi lỡ bấm Windows + G."),
"11-tat-meo-goi-y": ("Tắt mẹo và gợi ý Windows", "[Giao diện] Tắt thông báo 'mẹo dùng Windows' và các gợi ý ứng dụng chèn trong Start và Settings."),
"12-shortcut-cong-cu-it": ("Shortcut công cụ IT", "[Giao diện] Tạo thư mục 'IT Tools' trên Desktop có sẵn lối tắt tới Device Manager, Disk Management, Services, Event Viewer, Computer Management, Task Scheduler, Registry... để IT mở nhanh."),
"13-bat-restore-point": ("Bật System Restore + tạo điểm khôi phục", "[Hệ thống] Bật System Restore cho ổ C (dùng tối đa 5% dung lượng) và tạo sẵn điểm khôi phục 'ConsolePi - may moi' để quay về trạng thái máy mới cài khi cần. Đừng dùng chung với tuỳ chọn 'Tắt System Restore' của kịch bản."),
"14-tat-doi-may-in-mac-dinh": ("Giữ máy in mặc định", "[Giao diện] Máy in mặc định giữ nguyên, Windows không tự đổi sang máy in vừa dùng - hết cảnh in nhầm sang máy in khác."),
"15-tat-search-indexing": ("Tắt Windows Search indexing", "[Hiệu năng] Tắt lập chỉ mục tìm kiếm của Windows - máy yếu/ổ HDD đỡ bị giật ổ đĩa. Đổi lại tìm kiếm trong Outlook và Explorer sẽ chậm hơn."),
"16-pagefile-tu-dong": ("Pagefile do hệ thống quản lý", "[Hiệu năng] Để Windows tự quản lý bộ nhớ ảo (pagefile) - tránh lỗi thiếu bộ nhớ do cấu hình sai."),
"17-bat-wake-on-lan": ("Bật Wake-on-LAN", "[Mạng] Bật đánh thức máy từ xa qua mạng (Wake-on-LAN) để IT bật máy mà không cần tới tận nơi. Còn phải bật mục này trong BIOS."),
"18-tat-tiet-kiem-dien-card": ("Tắt tiết kiệm điện card mạng và USB", "[Mạng] Không cho Windows tự tắt card Wi-Fi/LAN và cổng USB để tiết kiệm điện - hết cảnh rớt mạng, chuột/USB đơ sau khi máy rảnh. Phần card mạng có hiệu lực sau khi khởi động lại."),
"19-bien-ban-ban-giao": ("Biên bản bàn giao máy", "[Bàn giao] Lập sẵn biên bản bàn giao máy: serial, model, CPU, RAM, ổ cứng, MAC, IP, bản Windows kèm danh sách phần mềm và driver đã cài - IT in ra hoặc lưu hồ sơ (thư mục C:\\ConsolePi\\reports)."),
"20-suc-khoe-o-cung": ("Kiểm tra sức khoẻ ổ cứng và RAM", "[Bàn giao] Kiểm tra sức khoẻ ổ cứng (SMART) và RAM ngay lúc cài, cảnh báo nếu ổ có dấu hiệu hỏng - tránh giao nhầm máy có ổ cứng sắp chết (nhất là máy cũ/tân trang)."),
"21-tat-remote-assistance": ("Tắt Remote Assistance", "[Bảo mật] Tắt tính năng mời người khác điều khiển máy (Remote Assistance). Remote Desktop không bị ảnh hưởng."),
"22-bat-openssh-server": ("Bật OpenSSH Server", "[Mạng] Cài và bật OpenSSH Server để IT đăng nhập dòng lệnh từ xa vào máy bằng ssh. Tự chạy cùng Windows, mở cổng 22. Cần có mạng nếu máy chưa có sẵn gói."),
"23-bat-chia-se-rieng-tu": ("Bật chia sẻ mạng riêng tư", "[Mạng] Bật tìm thấy máy trong mạng và chia sẻ file/máy in, nhưng chỉ cho mạng Private/Domain, không mở khi nối mạng công cộng."),
"24-mang-private": ("Đặt mạng hiện tại là Private", "[Mạng] Mạng đang bị đặt là Public thì đổi sang Private để máy thấy máy in và chia sẻ trong văn phòng. Mạng domain giữ nguyên."),
"25-bat-telnet-tftp": ("Bật Telnet và TFTP client", "[Mạng] Bật Telnet Client và TFTP Client để dân mạng kết nối, cấu hình switch/router ngay từ máy này."),
"26-tat-delivery-optimization": ("Tắt Delivery Optimization", "[Mạng] Windows Update chỉ tải từ Microsoft, không dùng băng thông mạng văn phòng để chia sẻ bản cập nhật cho máy khác."),
"27-mat-khau-khong-het-han": ("Mật khẩu local không hết hạn", "[Bảo mật] Tài khoản local không bị bắt đổi mật khẩu định kỳ (hết cảnh máy dùng chung bị khoá vì quá hạn). Tài khoản domain không bị ảnh hưởng."),
"28-khong-doi-mat-khau-khi-thuc": ("Không đòi mật khẩu khi thức máy", "[Bảo mật] Máy thức dậy từ chế độ ngủ vào thẳng desktop, không hỏi lại mật khẩu. Giảm bảo mật - chỉ dùng cho máy ở nơi an toàn."),
"29-bat-defender-realtime": ("Bật Defender real-time", "[Bảo mật] Đảm bảo Windows Defender luôn bật bảo vệ thời gian thực. Máy đã có phần mềm diệt virus khác thì tự bỏ qua."),
"30-bat-firewall": ("Bật Windows Firewall", "[Bảo mật] Đảm bảo Windows Firewall bật ở cả 3 loại mạng (Domain, Private, Public)."),
"31-tat-autorun-autoplay": ("Tắt AutoRun và AutoPlay", "[Bảo mật] Cắm USB/đĩa vào không tự chạy file bên trong và không hiện hộp AutoPlay - chặn virus lây qua USB."),
"32-tat-smbv1": ("Tắt SMBv1", "[Bảo mật] Tắt giao thức chia sẻ file đời cũ SMBv1 (đường lây của WannaCry). Máy in/NAS rất cũ chỉ biết SMBv1 sẽ không truy cập được."),
"33-hien-thong-tin-dang-nhap": ("Hiện thông tin chi tiết khi đăng nhập", "[Chẩn đoán] Lúc khởi động và đăng nhập, màn hình chờ hiện rõ Windows đang làm gì thay vì chỉ 'Please wait' - dễ tìm nguyên nhân máy vào desktop chậm."),
"34-tat-error-reporting": ("Tắt Windows Error Reporting", "[Bảo mật] Tắt báo cáo lỗi gửi về Microsoft và hộp thoại 'chương trình ngừng hoạt động' phiền phức."),
"35-chan-driver-qua-update": ("Chặn Windows Update tự cài driver", "[Hệ thống] Windows Update không tự thay driver đã cài - tránh bị ghi đè driver chính hãng IT đã cài rồi sinh lỗi màn hình/âm thanh/mạng."),
"36-dat-mo-ta-may": ("Đặt mô tả máy = Model + Serial", "[Bàn giao] Gắn mô tả 'Hãng Model | SN số-serial' cho máy - hiện trong danh sách mạng và AD, nhìn là biết máy nào."),
"37-bat-sandbox": ("Bật Windows Sandbox", "[Tính năng Windows] Bật Windows Sandbox: môi trường dùng một lần để chạy thử file lạ mà không ảnh hưởng máy. Cần Windows Pro/Enterprise (bản Home tự bỏ qua) và khởi động lại - đặt CUỐI kịch bản."),
"38-bat-hyperv": ("Bật Hyper-V", "[Tính năng Windows] Bật Hyper-V để chạy máy ảo ngay trên máy này. Cần Windows Pro/Enterprise và CPU hỗ trợ ảo hoá (bản Home tự bỏ qua), cần khởi động lại - đặt CUỐI kịch bản."),
"39-tat-tac-vu-theo-doi": ("Tắt tác vụ theo dõi", "[Riêng tư] Tắt các tác vụ chạy nền thu thập dữ liệu sử dụng (Compatibility Appraiser, CEIP) - máy bớt giật khi mới vào Windows."),
"40-tat-consumer-features": ("Tắt Consumer Features", "[Riêng tư] Không tự cài game, ứng dụng quảng cáo (Candy Crush...) khi đăng nhập bằng tài khoản Microsoft."),
"41-tat-welcome-experience": ("Tắt màn hình chào mừng sau cập nhật", "[Giao diện] Sau mỗi bản cập nhật không hiện màn hình chào mừng 'Hoàn tất thiết lập máy' - người dùng vào thẳng làm việc."),
"42-tat-hello-pin": ("Tắt yêu cầu tạo PIN Windows Hello", "[Giao diện] Lần đăng nhập đầu không bắt tạo PIN/Windows Hello. Đổi lại sẽ không dùng được Windows Hello."),
"43-tat-meetnow-people-ink": ("Tắt Meet Now, People, Ink trên taskbar", "[Giao diện] Ẩn nút Meet Now, danh bạ People và Windows Ink khỏi thanh tác vụ cho gọn."),
"44-dong-ho-hien-giay": ("Đồng hồ hiện giây", "[Giao diện] Đồng hồ trên thanh tác vụ hiện cả giây."),
"45-control-panel-icon-nho": ("Control Panel xem biểu tượng nhỏ", "[Giao diện] Control Panel mở sẵn ở dạng biểu tượng nhỏ, thấy hết mọi mục thay vì phải mở từng nhóm."),
"46-explorer-duong-dan-checkbox": ("Explorer hiện đường dẫn đầy đủ + ô chọn file", "[Giao diện] Thanh tiêu đề File Explorer hiện đường dẫn đầy đủ và có ô tick để chọn nhiều file dễ hơn."),
"47-tat-file-gan-day": ("Tắt 'file gần đây' trong Quick Access", "[Riêng tư] File Explorer không hiện 'file mở gần đây' và 'thư mục thường dùng' - riêng tư hơn cho máy dùng chung."),
"48-enable-linked-connections": ("Bật EnableLinkedConnections", "[Hệ thống] Ổ mạng đã map vẫn thấy khi chạy chương trình bằng quyền Administrator (hết lỗi 'không thấy ổ Z:' khi Run as administrator). Có hiệu lực sau khi khởi động lại."),
"49-hien-phien-ban-desktop": ("Hiện phiên bản Windows trên Desktop", "[Giao diện] Góc phải desktop hiện bản Windows và số build - IT liếc là biết máy đang chạy bản nào."),
"50-menu-mo-cmd-tai-day": ("Menu chuột phải: mở CMD/PowerShell tại đây", "[Giao diện] Chuột phải vào nền thư mục có thêm 'Open Command Prompt here' và 'Open PowerShell here' để mở dòng lệnh đúng thư mục đang đứng."),
"51-tat-copilot": ("Tắt Copilot", "[Riêng tư] Tắt Windows Copilot và ẩn nút Copilot trên thanh tác vụ."),
"52-tat-recall-ai": ("Tắt Recall và phân tích dữ liệu AI", "[Riêng tư] Tắt tính năng AI tự chụp và phân tích hoạt động trên màn hình (Windows Recall, Windows 11 bản mới)."),
"53-tat-advertising-id": ("Tắt Advertising ID", "[Riêng tư] Ứng dụng không dùng mã quảng cáo cá nhân của người dùng để theo dõi và nhắm quảng cáo."),
"54-tat-activity-history": ("Tắt Activity History", "[Riêng tư] Tắt lịch sử hoạt động (Timeline): Windows không ghi lại và không gửi lịch sử mở file, ứng dụng lên Microsoft."),
"55-tat-input-personalization": ("Tắt thu thập dữ liệu gõ phím và viết tay", "[Riêng tư] Windows không thu thập nội dung gõ phím, viết tay, danh bạ để 'cá nhân hoá'."),
"56-tat-feedback-prompts": ("Tắt hỏi ý kiến Windows", "[Giao diện] Tắt các thông báo xin ý kiến và khảo sát của Windows."),
"57-tat-tailored-experiences": ("Tắt trải nghiệm cá nhân hoá theo dữ liệu chẩn đoán", "[Riêng tư] Microsoft không dùng dữ liệu chẩn đoán của máy để gợi ý nội dung; tắt nhận diện giọng nói trực tuyến."),
"58-tat-dich-vu-diagtrack": ("Tắt dịch vụ DiagTrack và dmwappushservice", "[Riêng tư] Tắt hẳn dịch vụ thu thập dữ liệu chẩn đoán chạy nền - bổ sung cho tuỳ chọn giảm telemetry của kịch bản."),
"59-tat-chat-teams-taskbar": ("Ẩn nút Chat/Teams trên taskbar", "[Giao diện] Ẩn nút Chat (Teams cá nhân) khỏi thanh tác vụ Windows 11."),
"60-tat-theo-doi-start": ("Tắt theo dõi app và file gần đây trong Start", "[Giao diện] Menu Start không hiện ứng dụng và tài liệu dùng gần đây, phần 'Recommended' gọn hơn."),
"61-tat-search-highlights": ("Tắt Search Highlights", "[Giao diện] Ô tìm kiếm không hiện hình minh hoạ và sự kiện trong ngày (search highlights) - sạch hơn."),
"62-tat-aero-shake": ("Tắt Aero Shake", "[Giao diện] Lắc cửa sổ không còn làm thu nhỏ hết cửa sổ khác - tránh bấm nhầm khi kéo cửa sổ."),
"63-explorer-tien-trinh-rieng": ("Explorer mở cửa sổ trong tiến trình riêng", "[Giao diện] Mỗi cửa sổ thư mục chạy tiến trình riêng - một cửa sổ treo không kéo cả desktop treo theo."),
"64-tat-thong-bao-sync-explorer": ("Tắt quảng cáo đồng bộ trong Explorer", "[Giao diện] File Explorer không chèn quảng cáo, gợi ý dịch vụ đồng bộ (OneDrive...)."),
"65-khong-thumbsdb-mang": ("Không tạo Thumbs.db trên ổ mạng", "[Mạng] Không rải file Thumbs.db vào các thư mục mạng chia sẻ - thư mục dùng chung sạch hơn."),
"66-giam-tre-khoi-dong-app": ("Giảm trễ khởi động chương trình", "[Hiệu năng] Bỏ độ trễ mặc định trước khi chạy các chương trình khởi động cùng Windows - vào desktop dùng được nhanh hơn."),
"67-tat-may-nhanh": ("Tắt máy nhanh hơn", "[Hiệu năng] Rút thời gian chờ dịch vụ/ứng dụng treo lúc tắt máy từ 20 giây xuống 5 giây - tắt máy và khởi động lại nhanh hơn."),
"68-edge-khong-hoi-mac-dinh": ("Edge không hỏi làm trình duyệt mặc định", "[Edge] Edge không nhắc đặt làm trình duyệt mặc định, không đề nghị nhập dữ liệu từ trình duyệt khác và không hiện tab quảng cáo."),
"69-edge-tat-sidebar-shopping": ("Edge tắt sidebar, shopping, rewards", "[Edge] Edge không hiện thanh bên, trợ lý mua sắm và Microsoft Rewards - trình duyệt gọn, ít làm phiền."),
"70-office-tat-first-run": ("Office bỏ màn hình chào lần đầu", "[Office] Word/Excel/PowerPoint mở lên là dùng được ngay: tự chấp nhận điều khoản, bỏ video giới thiệu và cửa sổ chào lần đầu. Không kích hoạt bản quyền."),
"71-office-tat-telemetry": ("Office tắt telemetry", "[Office] Tắt việc Office gửi dữ liệu sử dụng (telemetry/CEIP) về Microsoft."),
"72-office-luu-may-mac-dinh": ("Office lưu trên máy mặc định", "[Office] Hộp thoại Save As của Office mặc định lưu trên máy thay vì OneDrive và bỏ nhắc đăng nhập OneDrive."),
"73-tat-dich-vu-xbox": ("Tắt dịch vụ Xbox", "[Dịch vụ] Tắt 4 dịch vụ Xbox chạy nền (đăng nhập, lưu game, mạng, thiết bị) mà máy văn phòng không dùng - nhẹ RAM, bớt tiến trình."),
"74-tat-dich-vu-it-dung": ("Tắt dịch vụ ít dùng", "[Dịch vụ] Tắt các dịch vụ ít khi dùng: Fax, Retail Demo, bản đồ ngoại tuyến, chia sẻ media của Windows Media Player, Windows Insider."),
"75-tat-sysmain-neu-ssd": ("Tắt SysMain (Superfetch) nếu ổ hệ thống là SSD", "[Dịch vụ] Máy dùng ổ SSD thì tắt SysMain (Superfetch) vì không còn ích lợi và gây ghi ổ thừa; máy ổ HDD giữ nguyên. Tự nhận biết loại ổ."),
"76-tat-llmnr": ("Tắt LLMNR", "[Bảo mật] Tắt LLMNR - đóng đường giả mạo tên máy trong mạng nội bộ để đánh cắp mật khẩu. Tên máy vẫn tìm bằng DNS bình thường."),
"77-tat-teredo": ("Tắt Teredo", "[Bảo mật] Tắt đường hầm Teredo (IPv6 qua IPv4) ít dùng, dễ làm máy phía sau NAT bị lộ ra Internet."),
"78-uu-tien-ipv4": ("Ưu tiên IPv4 hơn IPv6", "[Mạng] Ưu tiên IPv4 hơn IPv6 (vẫn giữ IPv6) - hết chậm do thử IPv6 trước ở mạng chưa hỗ trợ. Không ghi đè nếu IPv6 đã được cấu hình sẵn (vd tuỳ chọn Tắt IPv6). Có hiệu lực sau khi khởi động lại."),
"79-tat-tu-ket-noi-hotspot": ("Tắt tự kết nối Wi-Fi mở", "[Bảo mật] Windows không tự kết nối vào Wi-Fi mở hay Wi-Fi do người lạ chia sẻ."),
"80-bat-nla-rdp": ("Bật NLA cho Remote Desktop", "[Bảo mật] Remote Desktop phải xác thực trước khi hiện màn hình đăng nhập (NLA) - chặn tấn công dò mật khẩu RDP. Không tự bật Remote Desktop."),
"81-dam-bao-dong-bo-gio": ("Đảm bảo đồng bộ giờ tự động", "[Mạng] Bảo đảm đồng hồ máy tự đồng bộ với máy chủ giờ, tránh lệch giờ gây lỗi đăng nhập domain, chứng chỉ, email."),
"82-tat-remote-registry": ("Tắt Remote Registry", "[Bảo mật] Tắt dịch vụ cho phép người khác sửa registry của máy qua mạng - hiếm khi cần và nhiều rủi ro."),
"83-khoa-tai-khoan-sai-mat-khau": ("Khoá tài khoản khi nhập sai mật khẩu", "[Bảo mật] Nhập sai mật khẩu 10 lần thì khoá tài khoản 15 phút - chặn dò mật khẩu. Áp dụng cho tài khoản local."),
"84-tat-tai-khoan-guest": ("Tắt tài khoản Guest", "[Bảo mật] Đảm bảo tài khoản Guest (khách) luôn bị tắt."),
"85-bat-audit-dang-nhap": ("Bật nhật ký đăng nhập", "[Bảo mật] Bật nhật ký bảo mật: ai đăng nhập thành công/thất bại, tài khoản bị khoá, tạo/xoá tài khoản - cần khi điều tra sự cố."),
"86-tang-event-log": ("Tăng dung lượng Event Log", "[Bảo mật] Tăng dung lượng Event Log (Security 128 MB, System/Application 64 MB) để nhật ký không bị ghi đè sau vài ngày."),
"87-tat-powershell-v2": ("Tắt PowerShell 2.0", "[Bảo mật] Gỡ PowerShell 2.0 cũ (không có cơ chế ghi nhật ký và bảo vệ hiện đại, hay bị lợi dụng để né kiểm soát). PowerShell 5.1 dùng bình thường."),
"88-defender-bat-pua": ("Defender bật chặn phần mềm rác (PUA)", "[Bảo mật] Defender chặn thêm phần mềm rác (adware, bộ cài kèm phần mềm quảng cáo). Máy dùng phần mềm diệt virus khác thì bỏ qua."),
"89-defender-bat-network-protection": ("Defender bật Network Protection", "[Bảo mật] Defender chặn truy cập vào trang web và máy chủ độc hại. Máy dùng phần mềm diệt virus khác thì bỏ qua."),
"90-menu-take-ownership": ("Menu chuột phải: Take ownership", "[Menu] Chuột phải file/thư mục có 'Take ownership' - lấy lại quyền sở hữu khi gặp lỗi 'Access denied'. Cẩn thận, đừng dùng trên thư mục hệ thống."),
"91-menu-mo-bang-notepad": ("Menu chuột phải: Open with Notepad", "[Menu] Chuột phải bất kỳ file nào có 'Open with Notepad' để xem nhanh nội dung file không rõ định dạng."),
"92-dong-dau-may": ("Đóng dấu máy cài bởi Console System", "[Bàn giao] Đóng dấu máy 'cài bởi Console System' (ngày cài, build Windows) vào registry và file - sau này IT/GPO/Intune biết máy nào do hệ thống này cài."),
"93-ghi-cap-nhat-da-cai": ("Danh sách bản cập nhật đã cài", "[Bàn giao] Lập danh sách các bản cập nhật Windows (KB) đã có trên máy để biết máy mới cài đã được vá tới đâu (file CSV trong C:\\ConsolePi\\reports)."),
"94-ghi-tai-khoan-admin": ("Danh sách tài khoản và quyền admin", "[Bàn giao] Lập danh sách tài khoản trên máy và ai đang có quyền Administrator, để rà soát trước khi giao máy."),
"95-ghi-chuong-trinh-khoi-dong": ("Danh sách chương trình khởi động cùng Windows", "[Bàn giao] Liệt kê các chương trình tự chạy cùng Windows để phát hiện phần mềm lạ/không cần thiết trước khi giao máy."),
"96-bao-cao-pin-laptop": ("Báo cáo pin laptop", "[Bàn giao] Laptop: tạo báo cáo pin (dung lượng thiết kế so với hiện tại) để biết pin còn tốt không. Máy bàn tự bỏ qua."),
"97-ghi-ban-quyen-windows": ("Xem trạng thái bản quyền Windows", "[Bàn giao] Cho biết Windows trên máy đã kích hoạt bản quyền chưa (chỉ xem, không kích hoạt gì)."),
"98-ghi-tpm-secureboot-bitlocker": ("Kiểm tra TPM, Secure Boot, BitLocker", "[Bàn giao] Cho biết máy có TPM, Secure Boot, BitLocker không và đang chạy BIOS hay UEFI - biết ngay máy có lên được Windows 11 hoặc mã hoá ổ đĩa không."),
"99-thiet-bi-thieu-driver": ("Tìm thiết bị lỗi/thiếu driver", "[Bàn giao] Cho biết sau khi cài máy còn thiết bị nào lỗi hoặc thiếu driver (Device Manager có dấu chấm than) để cài bổ sung."),
"100-bat-wsl": ("Bật WSL (chạy Linux trên Windows)", "[Tính năng Windows] Bật nền tảng để chạy Linux trên Windows (WSL + Virtual Machine Platform), sẵn sàng cài Ubuntu... Cần khởi động lại - đặt CUỐI kịch bản."),
}
